// Subflow DT session : sortie 1 = msg.dtUser (autorisé), sortie 2 = 401/403 prêt pour http response
// OUTIL vide = session seule (portail, /auth/me)
const outil = env.get('OUTIL') || '';

function refus(code, erreur, effacer) {
    msg.statusCode = code;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };
    msg.payload = { erreur };
    if (effacer) msg.cookies = { dt_session: { value: '', maxAge: 0, path: '/data-tools', httpOnly: true, secure: true, sameSite: 'strict' } };
    return [null, msg];
}

const P = global.get('dt_params') || {};
const gl = (P.sessionGlissanteH || 12) * 3600e3, mx = (P.sessionMaxH || 24) * 3600e3;
const jeton = ((msg.req && msg.req.cookies) || {}).dt_session;
if (typeof jeton !== 'string' || jeton.length < 20 || jeton.length > 100) return refus(401, 'non_authentifie', !!jeton);

const cle = crypto.createHash('sha256').update(jeton).digest('hex');
const S = global.get('dt_sessions') || {};
const s = S[cle];
const now = Date.now();
if (!s || now - s.vu > gl || now - s.cree > mx) {
    if (s) { delete S[cle]; global.set('dt_sessions', S); }
    return refus(401, 'non_authentifie', true);
}
if (now - s.vu > 60000) { s.vu = now; global.set('dt_sessions', S); }

if (outil && !(s.outils.includes('*') || s.outils.includes(outil))) return refus(403, 'acces_refuse');

const methode = String(msg.req.method || 'GET').toUpperCase();
if (methode !== 'GET' && methode !== 'HEAD' && msg.req.headers['x-dt'] !== '1') return refus(403, 'entete_x_dt_manquant');

msg.dtUser = { login: s.login, nom: s.nom, admin: !!s.admin, outils: [...s.outils] };
return [msg, null];

