// GET /dt-api/auth/start?next=...  →  302 vers Microsoft (code + PKCE)
const b64url = b => b.toString('base64url');
const alea = n => b64url(crypto.randomBytes(n));

function redir(loc, cookies) {
    msg.statusCode = 302;
    msg.headers = { Location: loc, 'Cache-Control': 'no-store' };
    msg.payload = '';
    if (cookies) msg.cookies = cookies;
    return msg;
}
function nextSur(n) {
    if (typeof n !== 'string' || n.length > 500) return '/data-tools/';
    const ok = n.startsWith('/data-tools/') && !/\/\/|\\|\0/.test(n) && !/\/\.\.?(\/|$|\?)/.test(n)
        && !n.startsWith('/data-tools/login') && !n.startsWith('/data-tools/api/');
    return ok ? n : '/data-tools/';
}

const P = global.get('dt_params');
const tenant = env.get('DT_TENANT_ID');
const client = env.get('DT_CLIENT_ID');
const base = String(env.get('DT_BASE_URL') || '').replace(/\/+$/, '');
if (!P || !tenant || !client || !env.get('DT_CLIENT_SECRET') || !base) {
    node.warn('data-tools : DT_TENANT_ID, DT_CLIENT_ID, DT_CLIENT_SECRET ou DT_BASE_URL manquant');
    return redir('/data-tools/login/?erreur=config');
}

const now = Date.now();
const EN = global.get('dt_pending') || {};
for (const k of Object.keys(EN)) if (EN[k].exp < now) delete EN[k];
if (Object.keys(EN).length > 1000) return redir('/data-tools/login/?erreur=charge');

const state = alea(32), nonce = alea(32), verifier = alea(48), pre = alea(32);
const challenge = b64url(crypto.createHash('sha256').update(verifier).digest());
EN[state] = { pre, verifier, nonce, next: nextSur((msg.req.query || {}).next), exp: now + 10 * 60 * 1000 };
global.set('dt_pending', EN);

const q = {
    client_id: client,
    response_type: 'code',
    redirect_uri: base + '/data-tools/api/auth/callback',
    response_mode: 'query',
    scope: 'openid profile email',
    state, nonce,
    code_challenge: challenge,
    code_challenge_method: 'S256',
    prompt: 'select_account'
};
const qs = Object.entries(q).map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');

return redir(`https://login.microsoftonline.com/${encodeURIComponent(tenant)}/oauth2/v2.0/authorize?${qs}`, {
    dt_pre: { value: pre, httpOnly: true, secure: true, sameSite: 'lax', path: '/data-tools/api/auth/', maxAge: 10 * 60 * 1000 }
});

// GET /dt-api/auth/callback?code&state  →  sortie 1 : échange du code, sortie 2 : réponse d'erreur
function erreur(code) {
    msg.statusCode = 302;
    msg.headers = { Location: '/data-tools/login/?erreur=' + code, 'Cache-Control': 'no-store' };
    msg.payload = '';
    msg.cookies = { dt_pre: { value: '', maxAge: 0, path: '/data-tools/api/auth/', httpOnly: true, secure: true, sameSite: 'lax' } };
    return [null, msg];
}

const q = msg.req.query || {};
if (q.error) {
    node.warn(`data-tools : retour Microsoft en erreur ${String(q.error).slice(0, 60)} ${String(q.error_description || '').slice(0, 200)}`);
    return erreur(q.error === 'access_denied' ? 'annule' : 'ms');
}
if (typeof q.state !== 'string' || typeof q.code !== 'string' || q.code.length > 4000) return erreur('etat');

const EN = global.get('dt_pending') || {};
const p = EN[q.state];
if (p) { delete EN[q.state]; global.set('dt_pending', EN); }   // usage unique
if (!p || p.exp < Date.now()) return erreur('expire');

const pre = (msg.req.cookies || {}).dt_pre;
if (!pre || pre !== p.pre) return erreur('etat');                // anti login-CSRF

const tenant = env.get('DT_TENANT_ID');
const base = String(env.get('DT_BASE_URL') || '').replace(/\/+$/, '');
const form = {
    client_id: env.get('DT_CLIENT_ID'),
    client_secret: env.get('DT_CLIENT_SECRET'),
    grant_type: 'authorization_code',
    code: q.code,
    redirect_uri: base + '/data-tools/api/auth/callback',
    code_verifier: p.verifier,
    scope: 'openid profile email'
};

msg.dt = { nonce: p.nonce, next: p.next };
msg.url = `https://login.microsoftonline.com/${encodeURIComponent(tenant)}/oauth2/v2.0/token`;
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = Object.entries(form).map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');
return [msg, null];

// Réponse du endpoint token Microsoft → contrôles id_token → droits → session
// id_token reçu directement du endpoint token en TLS (client confidentiel) :
// signature non revérifiée (OIDC Core 3.1.3.7), claims contrôlés.
const d = msg.dt || {};
delete msg.dt;
const P = global.get('dt_params') || {};
const tenant = env.get('DT_TENANT_ID');
const client = env.get('DT_CLIENT_ID');

const effacerPre = { value: '', maxAge: 0, path: '/data-tools/api/auth/', httpOnly: true, secure: true, sameSite: 'lax' };
function fin(loc, cookieSession) {
    msg.statusCode = 302;
    msg.headers = { Location: loc, 'Cache-Control': 'no-store' };
    msg.payload = '';
    msg.cookies = { dt_pre: effacerPre };
    if (cookieSession) msg.cookies.dt_session = cookieSession;
    return msg;
}
const erreur = c => fin('/data-tools/login/?erreur=' + c);

if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload.id_token !== 'string') {
    const e = msg.payload && typeof msg.payload === 'object' ? `${msg.payload.error} ${msg.payload.error_description || ''}` : String(msg.payload);
    node.warn(`data-tools : échange du code refusé (${msg.statusCode}) ${e.slice(0, 300)}`);
    return erreur('jeton');
}

let c;
try { c = JSON.parse(Buffer.from(msg.payload.id_token.split('.')[1], 'base64url').toString('utf8')); }
catch (e) { return erreur('jeton'); }

const now = Math.floor(Date.now() / 1000);
if (c.iss !== `https://login.microsoftonline.com/${tenant}/v2.0` || c.aud !== client || c.tid !== tenant
    || c.nonce !== d.nonce || !(c.exp > now - 60)) {
    node.warn('data-tools : id_token rejeté (iss/aud/tid/nonce/exp)');
    return erreur('jeton');
}

const login = String(c.preferred_username || c.email || c.upn || '').toLowerCase().trim();
const domaine = login.split('@')[1] || '';
if (!(P.domaines || []).includes(domaine) || c.idp) {
    node.warn(`data-tools : compte refusé (domaine ou invité) ${login}`);
    return erreur('domaine');
}
if (c._claim_names && c._claim_names.groups) {
    node.warn(`data-tools : dépassement de groupes (plus de 200) pour ${login}`);
    return erreur('groupes');
}

// Droits = union des groupes configurés + compte de secours
const outils = new Set();
let admin = false;
const via = [];
for (const g of (Array.isArray(c.groups) ? c.groups : [])) {
    const r = (P.groupes || {})[g];
    if (!r) continue;
    (r.outils || []).forEach(o => outils.add(o));
    if (r.admin) admin = true;
    via.push(r.nom || g);
}
const cpt = (P.comptes || {})[login];
if (cpt) { (cpt.outils || []).forEach(o => outils.add(o)); if (cpt.admin) admin = true; via.push('compte'); }

if (!outils.size && !admin) {
    node.warn(`data-tools : aucun groupe autorisé pour ${login}`);
    return erreur('aucun_droit');
}

const jeton = crypto.randomBytes(32).toString('base64url');
const cle = crypto.createHash('sha256').update(jeton).digest('hex');
const S = global.get('dt_sessions') || {};
const t = Date.now();
S[cle] = { login, nom: String(c.name || login).slice(0, 120), admin, outils: [...outils], oid: c.oid, cree: t, vu: t };
global.set('dt_sessions', S);
node.log(`data-tools : connexion ${login} [${via.join(', ')}]${admin ? ' admin' : ''}`);

return fin('/data-tools/login/?fait=1&next=' + encodeURIComponent(d.next || '/data-tools/'),
    { value: jeton, httpOnly: true, secure: true, sameSite: 'strict', path: '/data-tools' });

// GET /dt-api/auth/check  (sous-requête auth_request de nginx)
// 204 = autorisé, 401 = pas de session, 403 = pas le droit sur l'outil ou URI suspecte
function rep(code) { msg.statusCode = code; msg.payload = ''; msg.headers = { 'Cache-Control': 'no-store' }; return msg; }

const brut = String(msg.req.headers['x-original-uri'] || '');
let chemin;
try { chemin = decodeURIComponent(brut.split('?')[0]); } catch (e) { return rep(403); }
// URI brute ($request_uri) : on refuse tout ce que nginx normaliserait autrement
if (!chemin.startsWith('/data-tools/') || /\/\/|\\|\0/.test(chemin) || /\/\.\.?(\/|$)/.test(chemin)) return rep(403);

const P = global.get('dt_params') || {};
const gl = (P.sessionGlissanteH || 12) * 3600e3, mx = (P.sessionMaxH || 24) * 3600e3;
const jeton = (msg.req.cookies || {}).dt_session;
if (typeof jeton !== 'string' || jeton.length < 20 || jeton.length > 100) return rep(401);
const cle = crypto.createHash('sha256').update(jeton).digest('hex');
const S = global.get('dt_sessions') || {};
const s = S[cle];
const now = Date.now();
if (!s || now - s.vu > gl || now - s.cree > mx) {
    if (s) { delete S[cle]; global.set('dt_sessions', S); }
    return rep(401);
}
if (now - s.vu > 60000) { s.vu = now; global.set('dt_sessions', S); }

let outil = '';
if (chemin.startsWith('/data-tools/api/')) {
    const m = chemin.match(/^\/data-tools\/api\/([a-z0-9-]+)\//);
    if (!m) return rep(403);
    outil = m[1];
} else {
    const m = chemin.match(/^\/data-tools\/([^\/]+)\//);
    if (m) outil = m[1];
}
if (!outil || s.outils.includes('*') || s.outils.includes(outil)) return rep(204);
return rep(403);

// GET /dt-api/auth/me  →  profil + catalogue des outils autorisés
const P = global.get('dt_params') || {};
const u = msg.dtUser;
const tout = u.outils.includes('*');
const catalogue = (P.outils || [])
    .filter(o => (tout || u.outils.includes(o.id)) && (o.publie || u.admin))
    .map(o => ({ id: o.id, nom: o.nom, description: o.description || '', publie: !!o.publie, url: `/data-tools/${o.id}/` }));
msg.payload = { login: u.login, nom: u.nom, admin: u.admin, outils: u.outils, catalogue };
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

// POST /dt-api/auth/logout (en-tête X-DT: 1)
msg.headers = { 'Cache-Control': 'no-store' };
if (msg.req.headers['x-dt'] !== '1') { msg.statusCode = 403; msg.payload = { erreur: 'entete_x_dt_manquant' }; return msg; }
const jeton = (msg.req.cookies || {}).dt_session;
if (typeof jeton === 'string' && jeton.length <= 100) {
    const cle = crypto.createHash('sha256').update(jeton).digest('hex');
    const S = global.get('dt_sessions') || {};
    if (S[cle]) { node.log(`data-tools : déconnexion ${S[cle].login}`); delete S[cle]; global.set('dt_sessions', S); }
}
msg.cookies = { dt_session: { value: '', maxAge: 0, path: '/data-tools', httpOnly: true, secure: true, sameSite: 'strict' } };
msg.statusCode = 200;
msg.payload = { ok: true };
return msg;

// Purge des sessions expirées et des connexions en attente
const P = global.get('dt_params') || {};
const gl = (P.sessionGlissanteH || 12) * 3600e3, mx = (P.sessionMaxH || 24) * 3600e3;
const now = Date.now();
const S = global.get('dt_sessions') || {};
let n = 0;
for (const k of Object.keys(S)) if (now - S[k].vu > gl || now - S[k].cree > mx) { delete S[k]; n++; }
global.set('dt_sessions', S);
const EN = global.get('dt_pending') || {};
for (const k of Object.keys(EN)) if (EN[k].exp < now) delete EN[k];
global.set('dt_pending', EN);
node.status({ fill: 'green', shape: 'dot', text: `${Object.keys(S).length} session(s) active(s), ${n} purgée(s) à ${new Date().toLocaleTimeString('fr-FR')}` });
return null;
